#!/usr/bin/env python3
"""Emit the exact direct-OutputStream PrintStream image; it has no host output."""
from pathlib import Path
IMAGE = bytes.fromhex("")
def build() -> bytes:
    return IMAGE
if __name__ == "__main__":
    (Path(__file__).parent / "java/io/PrintStream.class.hex").write_text(IMAGE.hex() + "\n")
